function validate([grid, stampHeight, stampWidth]) {
  if (!Array.isArray(grid) || grid.length < 1) return 'grid needs at least one row.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1) return 'grid needs at least one column.';
  if (grid.length * n > 200000) return 'grid may have at most 2 * 10^5 cells.';
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'Every row of grid must have the same length.';
  if (grid.some(row => row.some(v => v !== 0 && v !== 1))) return 'Each cell is 0 or 1.';
  for (const v of [stampHeight, stampWidth]) if (!Number.isInteger(v) || v < 1 || v > 100000) return 'stampHeight and stampWidth are between 1 and 10^5.';
  return null;
}

