function possibleToStamp(grid, stampHeight, stampWidth) {
  const m = grid.length;
  const n = grid[0].length;
  const blocked = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      blocked[r + 1][c + 1] = grid[r][c] + blocked[r][c + 1] + blocked[r + 1][c] - blocked[r][c];
    }
  }
  const diff = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let top = 0; top + stampHeight <= m; top++) {
    for (let left = 0; left + stampWidth <= n; left++) {
      const bottom = top + stampHeight;
      const right = left + stampWidth;
      const inside = blocked[bottom][right] - blocked[top][right] - blocked[bottom][left] + blocked[top][left];
      if (inside === 0) {
        diff[top][left]++;
        diff[top][right]--;
        diff[bottom][left]--;
        diff[bottom][right]++;
      }
    }
  }
  const cover = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      cover[r + 1][c + 1] = diff[r][c] + cover[r][c + 1] + cover[r + 1][c] - cover[r][c];
      if (grid[r][c] === 0 && cover[r + 1][c + 1] === 0) {
        return false;
      }
    }
  }
  return true;
}

