function possibleToStamp(grid, stampHeight, stampWidth) {
  const m = grid.length, n = grid[0].length;
  const covered = grid.map(row => row.map(() => false));
  for (let r = 0; r + stampHeight <= m; r++) {
    for (let c = 0; c + stampWidth <= n; c++) {
      let fits = true;
      for (let i = r; i < r + stampHeight; i++)
        for (let j = c; j < c + stampWidth; j++)
          if (grid[i][j] === 1) fits = false;
      if (!fits) continue;
      for (let i = r; i < r + stampHeight; i++)
        for (let j = c; j < c + stampWidth; j++) covered[i][j] = true;
    }
  }
  return grid.every((row, i) => row.every((v, j) => v === 1 || covered[i][j]));
}

