function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const n = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const pick = limit => 1 + Math.floor(rand() * limit);
  const stampHeight = large ? pick(8) : pick(m + 1);
  const stampWidth = large ? pick(8) : pick(n + 1);
  const mode = rand();
  let grid;
  if (mode < 0.6) {
    // Carve free regions out of a blocked grid with stamp-sized holes, so the answer starts as true.
    grid = Array.from({ length: m }, () => new Array(n).fill(1));
    const holes = large ? 400 : pick(4);
    for (let k = 0; k < holes && stampHeight <= m && stampWidth <= n; k++) {
      const top = Math.floor(rand() * (m - stampHeight + 1));
      const left = Math.floor(rand() * (n - stampWidth + 1));
      for (let i = top; i < top + stampHeight; i++)
        for (let j = left; j < left + stampWidth; j++) grid[i][j] = 0;
    }
    // Sometimes free one more cell, which may leave a spot no stamp can reach.
    if (mode < 0.3) grid[Math.floor(rand() * m)][Math.floor(rand() * n)] = 0;
  } else {
    const density = large ? rand() * 0.02 : rand() * 0.5;
    grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  }
  return [grid, stampHeight, stampWidth];
}
